// Arma el mensaje una sola vez y separa los destinos por canal
const falla = $('Cuando un flujo falla').first().json;
const filas = $input.all().map((i) => i.json);
const destinos = (tipo) => filas.filter((f) => f.tipo === tipo && f.valor).map((f) => String(f.valor).trim());
const telegram = destinos('telegram');
const correos = destinos('correo');
// La cuenta que envía: Gmail solo deja enviar desde la cuenta de la credencial SMTP. Sin fila, no se adivina
const remitente = destinos('remitente')[0] ?? null;

// Sin nadie a quien avisar, la alarma no puede quedarse callada: falla a la vista
if (!telegram.length && !correos.length) {
  throw new Error('Sin destino para las alertas: agrega en la tabla destinos_prueba una fila con tipo = telegram o tipo = correo');
}

const flujo = falla.workflow?.name ?? 'desconocido';
const paso = falla.execution?.lastNodeExecuted ?? 'el disparador';
const error = (falla.execution?.error?.message ?? falla.trigger?.error?.message ?? 'sin mensaje').slice(0, 500);
const enlace = falla.execution?.url ?? 'no hay (falló al arrancar)';
const hora = DateTime.now().setZone('America/Bogota').toFormat('dd/MM/yyyy HH:mm');

const texto = `⚠️ Falló un flujo de SolarAndes\n\nFlujo: ${flujo}\nPaso: ${paso}\nError: ${error}\nHora: ${hora}\n\nVer la ejecución: ${enlace}`;
return [{ json: { flujo, texto, asunto: `⚠️ Falló un flujo de SolarAndes: ${flujo}`, telegram, correos, remitente } }];

// Verde solo si el aviso llegó por los dos canales. Si uno falló, rojo: alguien se enteró, pero hay algo que arreglar
const { flujo, telegram: chats, correos, remitente } = $('Preparar alerta').first().json;
const fallo = (nodo) => {
  const salida = $(nodo).all();
  return !salida.length || salida.some((i) => i.json.error);
};
// El motivo más probable, para saber qué arreglar sin abrir n8n
const motivo = {
  telegram: chats.length ? 'revisa el bot o el chat_id' : 'no hay fila telegram en destinos_prueba',
  correo: !correos.length
    ? 'no hay fila correo en destinos_prueba'
    : !remitente
      ? 'no hay fila remitente en destinos_prueba'
      : 'revisa la credencial SMTP Correo SolarAndes',
};
const telegram = fallo('Avisar por Telegram');
const correo = fallo('Avisar por correo');

if (telegram && correo) {
  throw new Error(`No se pudo avisar por ningún canal de la falla de "${flujo}". Telegram: ${motivo.telegram}. Correo: ${motivo.correo}`);
}
if (telegram) throw new Error(`Telegram falló; el aviso de "${flujo}" llegó solo por correo: ${motivo.telegram}`);
if (correo) throw new Error(`El correo falló; el aviso de "${flujo}" llegó solo por Telegram: ${motivo.correo}`);
return [{ json: { entregado: ['telegram', 'correo'] } }];
